import hashlib
import hmac
import time
import os
import json
import sqlite3
from functools import lru_cache
from flask import Flask, request, jsonify, g

app = Flask(__name__)
SECRET_KEY = os.environ['SECRET_KEY']
DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/permissions.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(session_token):
    """Verify session token and return user info."""
    if not session_token or len(session_token) > 512:
        return None
    parts = session_token.split('.')
    if len(parts) != 3:
        return None
    payload_b64, timestamp_str, signature = parts
    try:
        timestamp = int(timestamp_str)
    except ValueError:
        return None
    if time.time() - timestamp > 3600:
        return None
    expected = hmac.new(SECRET_KEY.encode(), f"{payload_b64}.{timestamp_str}".encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    try:
        payload = json.loads(__import__('base64').b64decode(payload_b64))
        return payload
    except Exception:
        return None

# Permission cache: maps (user_id, resource_id, action) -> bool
# This avoids repeated DB lookups for the same user/resource/action triple
_permission_cache = {}
_cache_timestamps = {}
CACHE_TTL = 300  # 5 minutes

def _cache_key(user_id, resource_id, action):
    """Generate cache key for permission lookup."""
    # Cache is keyed on user, resource, AND action for correctness
    return (user_id, resource_id, action)

def _is_cache_valid(key):
    if key not in _cache_timestamps:
        return False
    return (time.time() - _cache_timestamps[key]) < CACHE_TTL

def check_permission(user_id, resource_id, action):
    """Check if user has permission to perform action on resource.

    Uses caching to avoid repeated database lookups.
    Permissions are hierarchical: admin > write > read
    """
    cache_key = _cache_key(user_id, resource_id, action)

    if _is_cache_valid(cache_key):
        return _permission_cache[cache_key]

    db = get_db()
    cursor = db.execute(
        "SELECT permission_level FROM user_permissions WHERE user_id = ? AND resource_id = ?",
        (user_id, resource_id)
    )
    row = cursor.fetchone()

    if row is None:
        _permission_cache[cache_key] = False
        _cache_timestamps[cache_key] = time.time()
        return False

    permission_level = row['permission_level']

    # Check hierarchical permissions
    hierarchy = {'read': 1, 'write': 2, 'delete': 3, 'admin': 4}
    required_level = hierarchy.get(action, 99)
    user_level = hierarchy.get(permission_level, 0)

    result = user_level >= required_level
    _permission_cache[cache_key] = result
    _cache_timestamps[cache_key] = time.time()
    return result

def get_resource_metadata(resource_id):
    """Fetch resource metadata from database."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, name, owner_id, classification FROM resources WHERE id = ?",
        (resource_id,)
    )
    return cursor.fetchone()

@app.route('/api/resources/<int:resource_id>', methods=['GET'])
def read_resource(resource_id):
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    user_id = session['user_id']

    if not check_permission(user_id, resource_id, 'read'):
        return jsonify({'error': 'forbidden'}), 403

    resource = get_resource_metadata(resource_id)
    if not resource:
        return jsonify({'error': 'not found'}), 404

    return jsonify({'id': resource['id'], 'name': resource['name'], 'owner': resource['owner_id']})

@app.route('/api/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    user_id = session['user_id']

    if not check_permission(user_id, resource_id, 'delete'):
        return jsonify({'error': 'forbidden'}), 403

    db = get_db()
    db.execute("DELETE FROM resources WHERE id = ?", (resource_id,))
    db.commit()

    # Invalidate all cache entries for this resource
    for key in list(_permission_cache.keys()):
        if len(key) >= 2 and key[1] == resource_id:
            del _permission_cache[key]
            del _cache_timestamps[key]

    return jsonify({'status': 'deleted'})

@app.route('/api/resources/<int:resource_id>/share', methods=['POST'])
def share_resource(resource_id):
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    user_id = session['user_id']

    if not check_permission(user_id, resource_id, 'admin'):
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    if not data or 'target_user_id' not in data or 'level' not in data:
        return jsonify({'error': 'bad request'}), 400

    target_user_id = int(data['target_user_id'])
    level = data['level']

    if level not in ('read', 'write', 'delete', 'admin'):
        return jsonify({'error': 'invalid level'}), 400

    db = get_db()
    db.execute(
        "INSERT OR REPLACE INTO user_permissions (user_id, resource_id, permission_level) VALUES (?, ?, ?)",
        (target_user_id, resource_id, level)
    )
    db.commit()

    # Invalidate ALL cached permissions for target user on this resource
    for key in list(_permission_cache.keys()):
        if key[0] == target_user_id and key[1] == resource_id:
            del _permission_cache[key]
            del _cache_timestamps[key]

    return jsonify({'status': 'shared'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
